INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Bubble Sort immer langsamer als Quick Sort?', 2, '[{"text": "Ja", "correct": true, "because": "O(n²) vs. O(n log n)"}, {"text": "Nein", "correct": false, "because": "Nur bei kleinen Listen vergleichbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Quick Sort in meinem Projekt?', 3, '[{"text": "Effiziente Sortierung", "correct": true, "because": "Schnell bei großen Daten"}, {"text": "Minimale Speichernutzung", "correct": false, "because": "Nicht primär"}, {"text": "Einfache Implementierung", "correct": false, "because": "Komplexer als Bubble Sort"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften unterscheiden Bubble Sort und Quick Sort?', 5, '[{"text": "Zeitkomplexität", "correct": true, "because": "O(n²) vs. O(n log n)"}, {"text": "In-Place-Sortierung", "correct": true, "because": "Beide möglich, Quick Sort effizienter"}, {"text": "Farbausgabe", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bubble Sort ist stabil. b) Quick Sort ist immer stabil.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Quick Sort ist nicht stabil"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl zwischen Bubble Sort und Quick Sort?', 4, '[{"text": "Datengröße", "correct": false, "because": "Entscheidend für Effizienz"}, {"text": "Sortierstabilität", "correct": false, "because": "Bubble Sort stabil, Quick Sort nicht"}, {"text": "Grafische Darstellung", "correct": true, "because": "Kein Sortierfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bubble Sort für große Datenmengen geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "O(n²) wird ineffizient"}, {"text": "Ja", "correct": false, "because": "Nur bei kleinen Listen praktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren wähle ich für eine fast sortierte Liste?', 3, '[{"text": "Bubble Sort", "correct": true, "because": "O(n) bei fast sortiert"}, {"text": "Quick Sort", "correct": false, "because": "O(n log n) auch bei fast sortiert"}, {"text": "Heap Sort", "correct": false, "because": "Immer O(n log n)"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Quick Sort effizient?', 5, '[{"text": "Divide-and-Conquer", "correct": true, "because": "Teilt Problem in kleinere Teile"}, {"text": "Pivot-Wahl", "correct": true, "because": "Beeinflusst Laufzeit"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär"}, {"text": "Statische Arrays", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bubble Sort ist einfach zu implementieren. b) Quick Sort ist immer schneller. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Quick Sort kann bei schlechter Pivotwahl O(n²) sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Implementierung von Bubble Sort?', 4, '[{"text": "Vergleichsoperation", "correct": false, "because": "Kern der Sortierung"}, {"text": "Tauschoperation", "correct": false, "because": "Elemente verschieben"}, {"text": "Rekursion", "correct": true, "because": "Bubble Sort ist iterativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Quick Sort für kleine Datenmengen übertrieben?', 2, '[{"text": "Ja", "correct": true, "because": "Bubble Sort oft einfacher"}, {"text": "Nein", "correct": false, "because": "Effizienz auch bei kleineren Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei Quick Sort entscheidend?', 4, '[{"text": "Pivot-Wahl", "correct": true, "because": "Teilt die Liste"}, {"text": "Partitionierung", "correct": true, "because": "Sortiert um Pivot"}, {"text": "Bubble-Pass", "correct": false, "because": "Bubble Sort spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bubble Sort nur für Lehrzwecke gut ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Praktisch bei kleinen, fast sortierten Daten"}, {"text": "Ja", "correct": false, "because": "Hat reale Anwendungsfälle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Quick Sort für eine große Liste?', 3, '[{"text": "Gute Pivot-Strategie", "correct": true, "because": "Minimiert Worst-Case"}, {"text": "Minimale Schleifen", "correct": false, "because": "Nicht primär"}, {"text": "Einfache Syntax", "correct": false, "because": "Effizienz zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bubble Sort hat O(n²) im Worst-Case. b) Quick Sort hat O(n) im Best-Case.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Quick Sort Best-Case ist O(n log n)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien bevorzugen Bubble Sort?', 5, '[{"text": "Kleine Datenmengen", "correct": true, "because": "Einfach und schnell genug"}, {"text": "Fast sortierte Listen", "correct": true, "because": "O(n) bei wenigen Tausch"}, {"text": "Große unsortierte Daten", "correct": false, "because": "Zu ineffizient"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "O(n²) zu langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Bubble Sort unwichtig?', 3, '[{"text": "Vergleichspaare", "correct": false, "because": "Kern der Logik"}, {"text": "Tauschoperationen", "correct": false, "because": "Sortierung ermöglichen"}, {"text": "Pivot-Element", "correct": true, "because": "Quick Sort spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Quick Sort immer rekursiv?', 3, '[{"text": "Ja", "correct": true, "because": "Divide-and-Conquer ist rekursiv"}, {"text": "Nein", "correct": false, "because": "Iterative Varianten selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bubble Sort auch bei großen Daten stabil bleibt?', 2, '[{"text": "Ja", "correct": true, "because": "Stabilität bleibt, Effizienz sinkt"}, {"text": "Nein", "correct": false, "because": "Stabilität unabhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Sortierverfahren wähle ich für eine Liste mit 10 Millionen Einträgen?', 4, '[{"text": "Quick Sort", "correct": true, "because": "O(n log n) effizient"}, {"text": "Bubble Sort", "correct": false, "because": "O(n²) zu langsam"}, {"text": "Insertion Sort", "correct": false, "because": "Auch O(n²)"}]');
